    else{response=success(exchange(transport,"/audio-uploads/"+job.get("object_id")+"/finalize",WireJson.bytes(WireJson.object()),clock));status=AudioUploadWire.status(response.body,job,clock.getAsLong(),false);AudioUploadWire.check("stored".equals(status.get("state")),"AUDIO_RECEIPT_STATE_INVALID");stored(job,status);}
