 synchronized int resumeAuthorized(MaterialApi.Transport transport,LongSupplier clock)throws IOException{preflight(transport,clock);List<Object> next=copy();int n=0;for(Object v:next){Map<String,Object> r=row(v);if(ours(r)&&"blocked".equals(r.get("state"))&&Arrays.asList("AUDIO_AUTH_REQUIRED","AUDIO_SCOPE_REQUIRED","AUDIO_CREDENTIAL_EXPIRED").contains(r.get("error"))){r.put("state","queued");r.put("next_attempt_at",0L);r.put("error","");n++;}}if(n>0)save(next);return n;}
 synchronized boolean retryBlocked(String id,MaterialApi.Transport transport,LongSupplier clock)throws IOException{check();Map<String,Object> prior=find(rows,id);AudioUploadWire.check(ours(prior)&&"blocked".equals(prior.get("state"))&&WireJson.list(prior.get("part_hashes")).size()==AudioUploadWire.parts(row(prior.get("manifest"))),"AUDIO_RETRY_NOT_READY");preflight(transport,clock);List<Object> next=copy();Map<String,Object> job=find(next,id);job.put("state","queued");job.put("error","");job.put("next_attempt_at",0L);save(next);return true;}
 private void removeOwnedPayload(Map<String,Object> r)throws IOException{check();AudioUploadWire.check(ours(r)&&r.get("receipt")!=null,"AUDIO_CLEANUP_UNCONFIRMED");for(String suffix:new String[]{".bin",".partial"}){File f=payload(r,suffix);if(f.exists())Files.delete(f.toPath());}sync(payloads);}
 public synchronized void close()throws IOException{if(!closed){closed=true;state.close();}}
